      evaluations: [{ method: "GET", path: "/v1/candidates/:candidateId/evaluations" }, { method: "POST", path: "/v1/candidates/:candidateId/evaluations" }, { method: "GET", path: "/v1/evaluations/:evaluationId" }, { method: "POST", path: "/v1/candidates/:candidateId/interpretability-packs" }],
