      promotions: [{ method: "POST", path: "/v1/candidates/:candidateId/promotions" }, { method: "GET", path: "/v1/promotions" }, { method: "GET", path: "/v1/promotions/:promotionId" }, { method: "POST", path: "/v1/promotions/:promotionId/decide" }],
      referrals: [{ method: "GET", path: "/v1/referrals" }, { method: "GET", path: "/v1/referrals/:referralId" }, { method: "POST", path: "/v1/referrals/:referralId/resolve" }],
